# Generated by forge. Foreign key columns a change adds to SQLAlchemy models get an
# index that leads with them (run by .forge/check.sh with the project's own Python,
# as advice). Usage:
#   python fk_index.py <forge-tmp>
# For each changed .py file: the foreign key columns of each declarative class
# (mapped_column(...) / Column(...) with a ForeignKey(...) argument, or a
# ForeignKeyConstraint in __table_args__) and each Table(...) call that were not in
# the base copy, and that no index leads with: index=True or unique=True on the
# column, primary_key=True when it is the table's first primary key column, or an
# Index / UniqueConstraint / PrimaryKeyConstraint whose first column it is.
# Exit 0: nothing found; 1: findings printed ("path:line message").
import ast
import os
import sys

TMP = sys.argv[1]


def read(path):
    try:
        with open(path, encoding="utf-8") as f:
            return f.read()
    except OSError:
        return None


def lines(name):
    return [l for l in (read(os.path.join(TMP, name)) or "").splitlines() if l]


def parse(text):
    try:
        return ast.parse(text or "")
    except (SyntaxError, ValueError):
        return None


def last(node):
    if isinstance(node, ast.Attribute):
        return node.attr
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Call):
        return last(node.func)
    return ""


def col_ref(node):
    """A column named by a string, a Name or an attribute (Post.author_id, author_id)."""
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return node.value.split(".")[-1]
    if isinstance(node, (ast.Name, ast.Attribute)):
        return last(node)
    return None


def kw(call, name):
    return any(k.arg == name and isinstance(k.value, ast.Constant) and k.value.value is True for k in call.keywords)


def has_fk(call):
    return any(isinstance(a, ast.Call) and last(a.func) == "ForeignKey" for a in call.args)


class Table:
    def __init__(self, name, line):
        self.name, self.line = name, line
        self.fks = {}  # column -> line
        self.leading = set()
        self.pks = []

    def column(self, name, call):
        if has_fk(call) and name not in self.fks:
            self.fks[name] = call.lineno
        if kw(call, "index") or kw(call, "unique"):
            self.leading.add(name)
        if kw(call, "primary_key"):
            self.pks.append(name)

    def constraint(self, call):
        kind = last(call.func)
        args = call.args[1:] if kind == "Index" else call.args
        if kind == "ForeignKeyConstraint":
            if call.args and isinstance(call.args[0], (ast.List, ast.Tuple)) and call.args[0].elts:
                name = col_ref(call.args[0].elts[0])
                if name and name not in self.fks:
                    self.fks[name] = call.lineno
            return
        if kind in ("Index", "UniqueConstraint", "PrimaryKeyConstraint") and args:
            name = col_ref(args[0])
            if name:
                self.leading.add(name)

    def unindexed(self):
        lead = set(self.leading)
        if self.pks:
            lead.add(self.pks[0])
        return {c: l for c, l in self.fks.items() if c not in lead}


def tables(tree):
    out = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef):
            t = Table(node.name, node.lineno)
            for stmt in node.body:
                targets, value = [], None
                if isinstance(stmt, ast.Assign):
                    targets, value = stmt.targets, stmt.value
                elif isinstance(stmt, ast.AnnAssign):
                    targets, value = [stmt.target], stmt.value
                for target in targets:
                    if not isinstance(target, ast.Name) or value is None:
                        continue
                    if target.id == "__table_args__":
                        for sub in ast.walk(value):
                            if isinstance(sub, ast.Call):
                                t.constraint(sub)
                    elif isinstance(value, ast.Call) and last(value.func) in ("mapped_column", "Column"):
                        named = value.args[0] if value.args and isinstance(value.args[0], ast.Constant) and isinstance(value.args[0].value, str) else None
                        t.column(named.value if named else target.id, value)
            if t.fks:
                out["class " + node.name] = t
        elif isinstance(node, ast.Call) and last(node.func) == "Table" and node.args:
            name = col_ref(node.args[0]) or "?"
            t = Table(name, node.lineno)
            for a in node.args[1:]:
                if isinstance(a, ast.Call) and last(a.func) == "Column" and a.args and isinstance(a.args[0], ast.Constant):
                    t.column(a.args[0].value, a)
                elif isinstance(a, ast.Call):
                    t.constraint(a)
            if t.fks:
                out["table " + name] = t
    return out


def main():
    found = []
    inbase = set(lines("inbase"))
    for path in lines("changed"):
        if not path.endswith(".py") or "/versions/" in path:
            continue
        tree = parse(read(path))
        if tree is None:
            continue
        base = {}
        if path in inbase:
            bt = parse(read(os.path.join(TMP, "base", path)))
            base = tables(bt) if bt is not None else {}
        for key, t in tables(tree).items():
            old = base.get(key)
            for col, line in sorted(t.unindexed().items(), key=lambda x: x[1]):
                if old is not None and col in old.fks:
                    continue
                found.append(f"{path}:{line} foreign key column {col} has no index that leads with it; PostgreSQL and SQLite do not index referencing columns, so joins on it and deletes of the referenced rows scan the table. If it is queried or the parent rows are deleted, add index=True (or an Index whose first column it is); otherwise say why not.")
    for f in found:
        print(f)
    return 1 if found else 0


if __name__ == "__main__":
    sys.exit(main())
